    <div style="background:#0b1729;border-radius:8px;padding:8px 12px;margin-top:6px;color:#e0f2fe;">(a) Rational/integer: √<span style="border-top:1px solid currentColor;padding:0 2px;">36</span> = 6 [1]. (b) Irrational: 10 is not a perfect square [1]. (c) Rational: ½ [1]. (d) Integer and rational [1].</div>
